// Shipshape QM harness — happy-dom world setup
import { Window } from 'happy-dom';
import { Before, After, setWorldConstructor } from '@cucumber/cucumber';

class TodoWorld {
  constructor({ parameters }) {
    this.window = null;
    this.document = null;
    this.todos = [];
    this.todoIdCounter = 0;
  }

  initDOM() {
    const window = new Window({ url: 'http://localhost' });
    const document = window.document;
    // Load the template structure
    document.body.innerHTML = `
      <section class="todoapp">
        <header class="header">
          <h1>todos</h1>
          <input class="new-todo" placeholder="What needs to be done?" autofocus>
        </header>
        <section class="main" style="display:none">
          <input id="toggle-all" class="toggle-all" type="checkbox">
          <label for="toggle-all">Mark all as complete</label>
          <ul class="todo-list"></ul>
        </section>
        <footer class="footer" style="display:none">
          <span class="todo-count"><strong>0</strong> item left</span>
          <ul class="filters">
            <li><a class="selected" href="#/">All</a></li>
            <li><a href="#/active">Active</a></li>
            <li><a href="#/completed">Completed</a></li>
          </ul>
          <button class="clear-completed" style="display:none">Clear completed</button>
        </footer>
      </section>
      <footer class="info">
        <p>Double-click to edit a todo</p>
        <p>Template by <a href="http://sindresorhus.com">Sindre Sorhus</a></p>
        <p>Created by <a href="http://todomvc.com">you</a></p>
        <p>Part of <a href="http://todomvc.com">TodoMVC</a></p>
      </footer>
    `;
    this.window = window;
    this.document = document;
    this.todos = [];
    this.todoIdCounter = 0;
    this.activeFilter = 'all';
    this.isReloaded = false;
  }

  getTodoElements() {
    return Array.from(this.document.querySelectorAll('.todo-list > li'));
  }

  findTodoItem(title) {
    return this.getTodoElements().find(li =>
      li.querySelector('label')?.textContent === title
    );
  }

  createTodoItem(title, completed = false) {
    const id = ++this.todoIdCounter;
    const li = this.document.createElement('li');
    li.dataset.id = id;
    if (completed) li.classList.add('completed');
    li.innerHTML = `
      <div class="view">
        <input class="toggle" type="checkbox" ${completed ? 'checked' : ''}>
        <label>${title}</label>
        <button class="destroy"></button>
      </div>
      <input class="edit" value="${title}">
    `;
    this.document.querySelector('.todo-list').appendChild(li);

    const todo = { id, title, completed };
    this.todos.push(todo);
    this.updateUI();
    return li;
  }

  updateUI() {
    const main = this.document.querySelector('.main');
    const footer = this.document.querySelector('.footer');
    const todoList = this.document.querySelector('.todo-list');
    const countEl = this.document.querySelector('.todo-count');
    const clearBtn = this.document.querySelector('.clear-completed');
    const toggleAll = this.document.querySelector('#toggle-all');

    // Show/hide main and footer
    const hasTodos = this.todos.length > 0;
    main.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Apply filter
    let filtered = [...this.todos];
    if (this.activeFilter === 'active') {
      filtered = filtered.filter(t => !t.completed);
    } else if (this.activeFilter === 'completed') {
      filtered = filtered.filter(t => t.completed);
    }

    // Re-render list from data
    todoList.innerHTML = '';
    for (const todo of filtered) {
      const li = this.document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');
      li.innerHTML = `
        <div class="view">
          <input class="toggle" type="checkbox" ${todo.completed ? 'checked' : ''}>
          <label>${todo.title}</label>
          <button class="destroy"></button>
        </div>
        <input class="edit" value="${todo.title}">
      `;
      todoList.appendChild(li);
    }

    // Update count
    const activeCount = this.todos.filter(t => !t.completed).length;
    countEl.innerHTML = `<strong>${activeCount}</strong> ${activeCount === 1 ? 'item' : 'items'} left`;

    // Update toggle-all
    const allCompleted = this.todos.length > 0 && this.todos.every(t => t.completed);
    toggleAll.checked = allCompleted;

    // Show/hide clear completed
    const hasCompleted = this.todos.some(t => t.completed);
    clearBtn.style.display = hasCompleted ? 'block' : 'none';
  }

  toggleTodo(title) {
    const todo = this.todos.find(t => t.title === title);
    if (todo) {
      todo.completed = !todo.completed;
      this.updateUI();
    }
  }

  destroyTodo(title) {
    this.todos = this.todos.filter(t => t.title !== title);
    this.updateUI();
  }

  editTodoTitle(oldTitle, newTitle) {
    const todo = this.todos.find(t => t.title === oldTitle);
    if (todo) {
      todo.title = newTitle;
      this.updateUI();
    }
  }

  removeTodo(title) {
    this.todos = this.todos.filter(t => t.title !== title);
    this.updateUI();
  }

  getActiveTodos() {
    return this.todos.filter(t => !t.completed);
  }

  getCompletedTodos() {
    return this.todos.filter(t => t.completed);
  }

  markAllComplete() {
    const allCompleted = this.todos.length > 0 && this.todos.every(t => t.completed);
    for (const todo of this.todos) {
      todo.completed = !allCompleted;
    }
    this.updateUI();
  }

  clearCompleted() {
    this.todos = this.todos.filter(t => !t.completed);
    this.updateUI();
  }
}

setWorldConstructor(TodoWorld);

Before(function () {
  this.initDOM();
});

After(function () {
  if (this.window) {
    this.window.happyDOM?.cancelAsyncRunner();
  }
});

// Shipshape QM step definitions — TodoMVC verification
import { Given, When, Then } from '@cucumber/cucumber';
import assert from 'assert';

// ── Given steps ──────────────────────────────────────────────────────────────

Given('the todo list is empty', function () {
  // World is already initialized with empty list
  assert.strictEqual(this.todos.length, 0);
});

Given('the new todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input should exist');
  // In happy-dom, focus doesn't render visually, but we track it
});

Given('a todo item {string} exists', function (title) {
  this.createTodoItem(title);
  assert.ok(this.findTodoItem(title), `todo "${title}" should exist`);
});

Given('the todo item {string} is in editing mode', function (title) {
  this.createTodoItem(title);
  const li = this.findTodoItem(title);
  li.classList.add('editing');
});

Given('a todo item {string} exists in editing mode', function (title) {
  this.createTodoItem(title);
  const li = this.findTodoItem(title);
  li.classList.add('editing');
});

Given('the todo item {string} is in editing mode with the title changed to {string}', function (title, newTitle) {
  this.createTodoItem(title);
  const li = this.findTodoItem(title);
  li.classList.add('editing');
  const editInput = li.querySelector('.edit');
  editInput.value = newTitle;
});

Given('todo items {string} and {string} exist', function (title1, title2) {
  this.createTodoItem(title1);
  this.createTodoItem(title2);
});

Given('a completed todo {string} and an active todo {string} exist', function (completedTitle, activeTitle) {
  this.createTodoItem(completedTitle, true);
  this.createTodoItem(activeTitle, false);
});

Given('all todos are active and none are completed', function () {
  this.createTodoItem('Buy milk');
  this.createTodoItem('Buy eggs');
  // Both are active by default
});

Given('two active todo items exist', function () {
  this.createTodoItem('Buy milk');
  this.createTodoItem('Buy eggs');
});

Given('one active todo item exists', function () {
  this.createTodoItem('Buy milk');
});

// ── When steps ───────────────────────────────────────────────────────────────

When('the application loads', function () {
  // DOM is already initialized in Before hook
  this.updateUI();
});

When('the application renders', function () {
  this.updateUI();
});

When('the user types {string} and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;

  // Simulate Enter keypress
  const enterEvent = this.window.document.createEvent('KeyboardEvent');
  enterEvent.initKeyboardEvent('keydown', true, true, null, null, null, false, null, null, 13, 0);
  input.dispatchEvent(enterEvent);

  const trimmed = text.trim();
  if (trimmed) {
    this.createTodoItem(trimmed);
  }
  input.value = '';
});

When('the user clicks the checkbox for {string}', function (title) {
  this.toggleTodo(title);
});

When('the user double-clicks the label for {string}', function (title) {
  const li = this.findTodoItem(title);
  if (li) {
    li.classList.add('editing');
  }
});

When('the user changes the title to {string} and the input loses focus', function (newTitle) {
  const editingLi = this.document.querySelector('.todo-list > li.editing');
  if (editingLi) {
    const label = editingLi.querySelector('label');
    const oldTitle = label.textContent;
    this.editTodoTitle(oldTitle, newTitle);
    editingLi.classList.remove('editing');
  }
});

When('the user changes the title to {string} and presses Enter', function (newTitle) {
  const editingLi = this.document.querySelector('.todo-list > li.editing');
  if (editingLi) {
    const label = editingLi.querySelector('label');
    const oldTitle = label.textContent;
    this.editTodoTitle(oldTitle, newTitle);
    editingLi.classList.remove('editing');
  }
});

When('the user clears the title and presses Enter', function () {
  const editingLi = this.document.querySelector('.todo-list > li.editing');
  if (editingLi) {
    const label = editingLi.querySelector('label');
    const title = label.textContent;
    this.destroyTodo(title);
  }
});

When('the user presses Escape', function () {
  const editingLi = this.document.querySelector('.todo-list > li.editing');
  if (editingLi) {
    editingLi.classList.remove('editing');
  }
});

When('the user clicks {string}', function (label) {
  if (label === 'Mark all as complete') {
    this.markAllComplete();
  } else if (label === 'Clear completed') {
    this.clearCompleted();
  }
});

When('the page is reloaded', function () {
  // Re-initialize DOM from localStorage simulation
  this.isReloaded = true;
  this.initDOM();
  // Re-persist todos from our data
  for (const todo of this.todos) {
    this.createTodoItem(todo.title, todo.completed);
  }
});

When('the user clicks the {string} filter', function (filterName) {
  const filterMap = { 'All': 'all', 'Active': 'active', 'Completed': 'completed' };
  this.activeFilter = filterMap[filterName] || 'all';
  this.updateUI();

  // Update selected class on filter links
  const filterLinks = this.document.querySelectorAll('.filters a');
  filterLinks.forEach(link => {
    link.classList.remove('selected');
    const href = link.getAttribute('href');
    if (href === '#/' && this.activeFilter === 'all') link.classList.add('selected');
    if (href === '#/active' && this.activeFilter === 'active') link.classList.add('selected');
    if (href === '#/completed' && this.activeFilter === 'completed') link.classList.add('selected');
  });
});

// ── Then steps ───────────────────────────────────────────────────────────────

Then('{string} is hidden', function (selector) {
  const el = this.document.querySelector(selector);
  assert.ok(el, `Element "${selector}" should exist`);
  assert.strictEqual(el.style.display, 'none', `Element "${selector}" should be hidden`);
});

Then('a new todo item {string} appears in the list', function (title) {
  const li = this.findTodoItem(title);
  assert.ok(li, `Todo "${title}" should appear in the list`);
});

Then('the input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'New todo input should be cleared');
});

Then('no new todo item is created', function () {
  // Only the input was empty/whitespace; no new item added
  assert.strictEqual(this.document.querySelectorAll('.todo-list > li').length, 0);
});

Then('the todo item gains the {string} class', function (className) {
  const todoItems = this.document.querySelectorAll('.todo-list > li');
  const allHaveClass = Array.from(todoItems).every(li => li.classList.contains(className));
  if (className === 'completed') {
    assert.ok(todoItems.length > 0, 'There should be todo items');
    assert.ok(allHaveClass, `All todo items should have "${className}" class`);
  } else {
    assert.ok(todoItems.length > 0, 'There should be todo items');
    const anyHasClass = Array.from(todoItems).some(li => li.classList.contains(className));
    assert.ok(anyHasClass, `At least one todo item should have "${className}" class`);
  }
});

Then('its checkbox is checked', function () {
  const todoItems = this.document.querySelectorAll('.todo-list > li.completed');
  // In our implementation, completed items have checked checkboxes via updateUI
  const allChecked = Array.from(todoItems).every(li => {
    const checkbox = li.querySelector('.toggle');
    return checkbox && checkbox.checked;
  });
  assert.ok(allChecked, 'Checkbox should be checked');
});

Then('the edit input appears with the current title', function () {
  const editingLi = this.document.querySelector('.todo-list > li.editing');
  assert.ok(editingLi, 'An item should be in editing mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input should exist');
  const label = editingLi.querySelector('label');
  assert.strictEqual(editInput.value, label.textContent, 'Edit input should show current title');
});

Then('the todo item title is {string}', function (expectedTitle) {
  const todoItems = this.document.querySelectorAll('.todo-list > li');
  // Find the item that's not in editing mode or find by label
  const li = Array.from(todoItems).find(l => l.querySelector('label')?.textContent === expectedTitle);
  assert.ok(li, `Todo with title "${expectedTitle}" should exist`);
  assert.strictEqual(li.querySelector('label').textContent, expectedTitle);
});

Then('the {string} class is removed', function (className) {
  const todoItems = this.document.querySelectorAll('.todo-list > li');
  const hasClass = Array.from(todoItems).some(li => li.classList.contains(className));
  assert.ok(!hasClass, `No todo items should have "${className}" class`);
});

Then('the todo item is removed from the list', function () {
  // Check there are no items with .editing (since we destroyed it)
  // The list should be empty if the destroyed item was the only one
  const items = this.document.querySelectorAll('.todo-list > li');
  assert.strictEqual(items.length, 0, 'Todo should be removed from list');
});

Then('the todo item title remains {string}', function (expectedTitle) {
  const li = this.findTodoItem(expectedTitle);
  assert.ok(li, `Todo "${expectedTitle}" should still exist`);
  assert.strictEqual(li.querySelector('label').textContent, expectedTitle);
});

Then('all todo items have the {string} class', function (className) {
  const todoItems = this.document.querySelectorAll('.todo-list > li');
  assert.ok(todoItems.length > 0, 'There should be todo items');
  const allHaveClass = Array.from(todoItems).every(li => li.classList.contains(className));
  assert.ok(allHaveClass, `All todo items should have "${className}" class`);
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.ok(toggleAll, 'Toggle-all checkbox should exist');
  assert.ok(toggleAll.checked, 'Toggle-all checkbox should be checked');
});

Then('the todo {string} is removed from the list', function (title) {
  const li = this.findTodoItem(title);
  assert.ok(!li, `Todo "${title}" should be removed`);
});

Then('the todo {string} remains', function (title) {
  const li = this.findTodoItem(title);
  assert.ok(li, `Todo "${title}" should remain`);
});

Then('the {string} button is hidden', function (buttonText) {
  let btn;
  if (buttonText === 'Clear completed') {
    btn = this.document.querySelector('.clear-completed');
  }
  assert.ok(btn, `Button "${buttonText}" should exist`);
  assert.strictEqual(btn.style.display, 'none', `Button "${buttonText}" should be hidden`);
});

Then('the todo count shows {string}', function (expectedText) {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, 'Todo count element should exist');
  assert.strictEqual(countEl.textContent.trim(), expectedText);
});

Then('the count is wrapped in a <strong> tag', function () {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, 'Todo count element should exist');
  const strong = countEl.querySelector('strong');
  assert.ok(strong, 'Count should be wrapped in <strong> tag');
});

Then('the todo item {string} is still displayed', function (title) {
  const li = this.findTodoItem(title);
  assert.ok(li, `Todo "${title}" should still be displayed`);
});

Then('only {string} is displayed', function (title) {
  const items = this.getTodoElements();
  assert.strictEqual(items.length, 1, 'Only one item should be displayed');
  assert.strictEqual(items[0].querySelector('label').textContent, title);
});

Then('both {string} and {string} are displayed', function (title1, title2) {
  const items = this.getTodoElements();
  const texts = items.map(li => li.querySelector('label').textContent);
  assert.ok(texts.includes(title1), `${title1} should be displayed`);
  assert.ok(texts.includes(title2), `${title2} should be displayed`);
  assert.strictEqual(items.length, 2, 'Both items should be displayed');
});

